INSERT INTO `cpl` (`id_cpl`, `id_prodi`, `kode_cpl`, `deskripsi`) VALUES
(1, 1, 'CPL-01', 'Mampu menerapkan prinsip matematika, sains, dan rekayasa teknik elektro berdasarkan teknologi informasi untuk menganalisis dan mengimplementasikan untuk mendapatkan pemahaman menyeluruh tentang prinsip-prinsip teknik elektro'),
(2, 1, 'CPL-02', 'Mampu merancang sistem, komponen, atau proses teknik elektro berbasis teknologi terkini dengan mempertimbangkan aspek keselamatan,kesehatan, etika, ekonomi, sosial, lingkungan, hukum, dan prinsip keberlanjutan sehingga mampu mengenali dan memanfaatkan potensi sumber daya lokal dan nasional dengan wawasan global.'),
(3, 1, 'CPL-03', 'Mampu merancang dan/atau melakukan eksperimen di laboratorium atau lapangan, menganalisis serta menginterpretasikan data secara tepat untuk mendukung pengambilan keputusan teknis.'),
(4, 1, 'CPL-04', 'Mampu mengidentifikasi, merumuskan, dan menyelesaikan permasalahan teknik elektro yang kompleks dengan pendekatan analitis dan inovatif.'),
(5, 1, 'CPL-05', 'Mampu memilih dan menggunakan metode, perangkat keras, perangkat lunak, serta alat bantu rekayasa modern yang relevan untuk praktik teknik elektro.'),
(6, 1, 'CPL-06', 'Mampu berkomunikasi secara efektif secara lisan dan tulisan dalam konteks profesional akademik multidisiplin dan multikultural.'),
(7, 1, 'CPL-07', 'Mampu merencanakan, mengelola, mengevaluasi dan menyelesaikan tugas di dalam batasan yang ada.'),
(8, 1, 'CPL-08', 'Mampu bekerja dalam tim multidisiplin dan multikultural serta berkolaborasi dalam mengembangkan inovasi atau peluang kewirausahaan berbasis teknologi elektro.'),
(9, 1, 'CPL-09', 'Mampu bertanggung jawab kepada masyarakat dan mematuhi etika profesional dalam menyelesaikan permasalahan teknik.'),
(10, 1, 'CPL-10', 'Mampu menginternalisasi nilai-nilai keislaman dan kemuhammadiyahan serta menjadikan pembelajaran sepanjang hayat sebagai bagian dari pengembangan diri dalam menghadapi tantangan global sesuai isu- isu terkini '),
(11, 2, 'CPL-01', 'Mampu menerapkan pengetahuan matematika, ilmu alam, dan teknologi informasi untuk memahami prinsip-prinsip dasar teknik sumber daya air.'),
(12, 2, 'CPL-02', 'Mampu merancang sistem jaringan bangunan air dengan mempertimbangkan aspek hukum, ekonomi, lingkungan, sosial, politik, kesehatan dan keselamatan, serta keberlanjutan, serta mengenali dan/atau memanfaatkan potensi sumber daya local dan nasional dengan perspektif global.'),
(13, 2, 'CPL-03', 'Mampu merancang dan melakukan eksperimen laboratorium maupun pengamatan lapangan serta mampu menganalisis dan menginterpretasikan data untuk mendukung penilaian teknik sumber daya air.'),
(14, 2, 'CPL-04', 'Mampu mengidentifikasi, merumuskan, menganalisis, dan memecahkan permasalahan kompleks di bidang teknik sumber daya air.'),
(15, 2, 'CPL-05', 'Mampu menerapkan metode, keterampilan, dan alat rekayasa modern dalam praktik teknik sumber daya air.'),
(16, 2, 'CPL-06', 'Mampu berkomunikasi secara efektif baik secara lisan dan tertulis dalam menyampaikan ide maupun hasil analisis.'),
(17, 2, 'CPL-07', 'Mampu merencanakan, melaksanakan, dan mengevaluasi tugas Teknik sumber daya air sesuai dengan batasan yang tersedia.'),
(18, 2, 'CPL-08', 'Mampu bekerja dalam tim multidisiplin dan multicultural.'),
(19, 2, 'CPL-09', 'Mampu bertanggung jawab secara profesional dan mematuhi etika profesional terhadap masyarakat dalam merancang dan mengelola infrastruktur Teknik sumber daya air yang aman.'),
(20, 2, 'CPL-10', 'Mampu menyadari pentingnya pembelajaran sepanjang hayat dengan menerapkan Al Islam Kemuhammadiyahan dan terus mengakses pengetahuan terbaru dan isu yang sejalan dengan perkembangan zaman di bidang sumber daya air.'),
(21, 3, 'CPL-01', 'Lulusan mampu menunjukkan integritas, etika profesi, nilai-nilai keislaman, tanggung jawab sosial, dan komitmen terhadap keberlanjutan dalam setiap praktik arsitektur, serta mampu mengambil keputusan profesional yang adil, aman, dan bermanfaat bagi masyarakat.'),
(22, 3, 'CPL-02', 'Lulusan mampu merancang bangunan, interior, tapak, dan ruang luar secara kreatif, humanis, inklusif, dan berkelanjutan, dengan mensintesis teori, konsep, konteks, nilai Islami, serta kebutuhan pengguna secara mandiri dan terukur.'),
(23, 3, 'CPL-03', 'Lulusan mampu menganalisis dan mengevaluasi sistem struktur beton, baja, dan konstruksi bangunan lainnya, serta menghasilkan solusi struktur dan ruang melalui penerapan mekanika bangunan, gaya–beban, serta pendekatan parametrik dalam desain.'),
(24, 3, 'CPL-04', 'Lulusan mampu mengkaji dan mengevaluasi sejarah arsitektur dunia, arsitektur Islam, dan perkembangan arsitektur kontemporer, serta mengintegrasikan wawasan tersebut sebagai dasar pengambilan keputusan dalam proses desain'),
(25, 3, 'CPL-05', 'Lulusan mampu menghasilkan komunikasi visual arsitektur dalam bentuk gambar 2D, 3D, simulasi, dan presentasi profesional, serta mendemonstrasikan kemampuan menyampaikan ide desain secara efektif kepada berbagai pemangku kepentingan.'),
(26, 3, 'CPL-06', 'Lulusan mampu merancang dan mengevaluasi struktur, konstruksi, material, dan detail bangunan berdasarkan kaidah teknis, aspek estetika, keamanan, topografi, bangunan bertingkat, serta teknologi yang relevan.'),
(27, 3, 'CPL-07', 'Lulusan mampu merancang dan mengevaluasi sistem utilitas dan kenyamanan bangunan (termal, penghawaan, pencahayaan, akustik) dengan mempertimbangkan iklim tropis, kondisi lokal, serta prinsip arsitektur hijau.'),
(28, 3, 'CPL-08', 'Lulusan mampu menghasilkan gambar kerja, laporan teknis-ilmiah, serta model digital berbasis BIM secara profesional, serta mampu mendiseminasikan hasil perancangan melalui publikasi akademik dan media digital.'),
(34, 5, 'CPL-01', 'Capaian Pembelajaran Lulusan 01 Informatika'),
(35, 5, 'CPL-02', 'Capaian Pembelajaran Lulusan 02 Informatika'),
(36, 5, 'CPL-03', 'Capaian Pembelajaran Lulusan 03 Informatika'),
(37, 5, 'CPL-04', 'Capaian Pembelajaran Lulusan 04 Informatika'),
(38, 5, 'CPL-05', 'Capaian Pembelajaran Lulusan 05 Informatika');
