INSERT INTO `cpmk` (`id`, `id_mk`, `kode_cpmk`, `deskripsi`, `bobot`, `created_at`, `updated_at`, `matched_cpl`) VALUES
('00446d37-6411-4ee4-a64a-5c6d2b72e768', 'e9c0f3fa-a9ba-432a-9a56-1adb88b462ae', 'CPMK-5', 'Mampu menyusun rancangan proposal penelitian dengan format ilmiah yang baku.', 20.00, '2026-01-16 22:56:52', '2026-01-17 00:58:11', ''),
('0056032d-190c-4099-940e-8e611d6c16f2', '2aaaf8e5-a8c5-4a4f-8a1b-1f977c1dfa75', 'CPMK-4', 'Mampu melakukan simulasi sistem komunikasi dasar menggunakan perangkat lunak (MATLAB/ GNU Radio/ sejenisnya) untuk memodelkan karakteristik sinyal dan sistem.', 20.00, '2026-01-17 00:58:18', '2026-01-17 00:58:18', ''),
('00563f17-5e22-449d-8fe5-7c030ebd70a5', '66cc25e3-402c-49de-9ba4-6fd803e0795a', 'CPMK-2', 'Mahasiswa mampu menganalisis sistem struktur baja berdasarkan beban dan fungsi bangunan.', 0.20, '2026-01-16 22:56:47', '2026-01-17 00:52:38', ''),
('006ec39e-45f8-4d8e-92f4-05c815347cfe', 'cbaa232e-a1df-426b-bdea-af5c42b8da05', 'CPMK-4', 'Mampu mengimplementasikan desain dalam bentuk prototipe/perangkat keras atau perangkat lunak, melakukan simulasi atau eksperimen, serta mengevaluasi performa sistem dengan metode pengujian dan alat bantu rekayasa modern.', 16.66, '2026-01-17 00:58:36', '2026-01-17 00:58:36', ''),
('0076df83-3825-442f-a333-101ddba85852', 'ac2ca539-9694-48b3-93f8-0db6de719278', 'CPMK-4', 'Mampu berkolaborasi dalam tim multidisiplin untuk mengembangkan solusi perancangan yang komprehensif.', 0.20, '2026-01-16 22:56:58', '2026-01-17 00:52:38', 'CPL-01, CPL-02'),
('007ab743-1d0a-4701-ad65-903ea88c798d', '8e79442e-a7af-4718-984d-1b0995f8820b', 'CPMK-3', 'Mahasiswa mampu memilih material dan sistem konstruksi yang tepat dengan mempertimbangkan aspek teknis, estetika, keberlanjutan, dan nilai Islami.', 0.20, '2026-01-16 22:56:45', '2026-01-17 00:52:38', ''),
('00905cc5-e8d2-4b83-a695-b451382b957b', '6f7a91bc-8054-45d6-ac08-84f31ec6b0d8', 'CPMK-2', 'Mampu menjelaskan konsep dasar sistem komunikasi cerdas dan peran AI/Machine Learning dalam teknologi komunikasi modern.', 20.00, '2026-01-17 00:58:35', '2026-01-17 00:58:35', ''),
('00c49185-5232-4b17-beaf-4b22122f7bf5', 'e001a246-3d23-4e88-b982-3abbf29caf15', 'CPMK-1', 'Mahasiswa mampu mengidentifikasi potensi dan kendala tapak untuk bangunan fungsi tunggal skala menengah (2ΓÇô3 lantai).', 0.20, '2026-01-16 22:56:44', '2026-01-17 00:52:38', ''),
('00d21b58-9cba-4a56-916c-d91b3aaa649c', '80b4b948-ddb7-40e4-89d1-ba78be1e1feb', 'CPMK-1', 'Mahasiswa mampu menjelaskan prinsip dasar struktur bangunan, elemen penyusunnya, dan hubungan antara bentuk, material, serta sistem struktur terhadap stabilitas bangunan.', 0.20, '2026-01-16 22:56:44', '2026-01-17 00:52:38', ''),
('00e1c672-f46a-4de8-8e08-12dc0d5b70cf', '7a178668-cb76-41c6-a739-4a69f2959af0', 'CPMK-2', 'Mahasiswa mampu menguraikan prinsip, norma, dan kode etik profesi arsitektur, termasuk standar yang berlaku di Indonesia dan internasional.', 0.00, '2026-01-16 22:56:51', '2026-01-17 00:58:10', ''),
('01127589-4381-44e4-bbda-d5cfad44cdf7', '9ad1d2e1-8ed4-4204-bb39-d149a56997cb', 'CPMK-2', 'Mahasiswa mampu menghitung beban, gaya, dan deformasi pada struktur tinggi.', 0.20, '2026-01-16 22:56:50', '2026-01-17 00:52:38', ''),
('01478f91-8c22-4a30-8e9e-e158f53d86b1', '8762c433-6fdd-462b-8494-1d264eb3dd15', 'CPMK-4', 'Mahasiswa mampu menerapkan prinsip mekanika teknik untuk memecahkan kasus sederhana dalam perancangan struktur bangunan arsitektur.', 0.20, '2026-01-16 22:56:40', '2026-01-17 00:52:38', ''),
('01ddd612-7233-4e1e-9b3c-f783b2dc5ea4', '7efb0e90-2bee-4647-8438-88bd0aebaa96', 'CPMK-3', 'Mampu menganalisis spesifikasi teknis dan karakteristik rangkaian analog/digital untuk menentukan solusi desain yang tepat.', 20.00, '2026-01-17 00:58:26', '2026-01-17 00:58:26', ''),
('01f27b3d-03ba-433e-b35f-9c61be953e1f', '33fc18df-fd5b-45c5-9893-71f90e37ba61', 'CPMK-3', 'Mahasiswa mampu mengetahui┬á dan memahami cara kerja manajemen proyek perangkat lunak', 0.09, '2026-01-16 23:21:00', '2026-01-17 00:49:33', ''),
('02040b1c-aaec-48ca-b172-4cf1eb6950a2', '11987187-2fc3-48d5-9f09-12e6310d35e5', 'CPMK-2', 'Mampu menjelaskan konsep dasar matriks, vektor, sistem persamaan linear, dan determinan.', 21.43, '2026-01-17 00:58:13', '2026-01-17 00:58:13', ''),
('022ab92a-ea4e-4d57-a1e5-728611754fca', 'b0a2bd49-8e66-4f01-b099-3182c92da4b4', 'CPMK-1', 'Memahami prinsip dasar matematika teknik yang relevan dengan arsitektur.', 0.20, '2026-01-16 22:56:41', '2026-01-17 00:52:38', ''),
('023afe75-fe00-4e6e-b439-bd9604a716ad', 'fef3d744-dfa4-4059-aa84-578d1a6d432f', 'CPMK-2', 'Mahasiswa mampu mengidentifikasi elemen dan tipologi arsitektur Islam di dunia dan di Nusantara.', 0.20, '2026-01-16 22:56:42', '2026-01-17 00:52:38', ''),
('026c709a-2e75-433b-86cd-7cb66a81726a', '881a35ab-2427-447e-bb8a-e26a566f677a', 'CPMK-4', 'Mahasiswa mampu mengintegrasikan perancangan ruang luar dengan bangunan dan lingkungan sekitarnya secara harmonis.', 0.20, '2026-01-16 22:56:47', '2026-01-17 00:52:38', ''),
('02b4ba65-1c28-4718-836e-4fb643e28567', '5aec8529-0bc9-43dc-8b16-9d6350ca3958', 'CPMK-4', 'Mampu melakukan pengujian dan pengukuran tegangan tinggi dengan prosedur laboratorium yang sesuai standar keselamatan.', 20.00, '2026-01-17 00:58:24', '2026-01-17 00:58:24', ''),
('02b711fe-099d-48f5-967e-8592308bf338', '73525a7c-f212-4b45-a48c-f6283a195746', 'CPMK-3', 'Mahasiswa mampu mengembangkan konsep desain kawasan perkotaan yang humanis, berkelanjutan, kontekstual, dan berlandaskan nilai Islami.', 0.20, '2026-01-16 22:56:48', '2026-01-17 00:52:38', ''),
('02d51508-b5c0-49d6-b60a-d02802e615ee', '6f7a91bc-8054-45d6-ac08-84f31ec6b0d8', 'CPMK-1', 'Mata kuliah ini membahas penerapan kecerdasan buatan (AI), machine learning (ML), dan algoritma adaptif dalam sistem komunikasi modern.', 20.00, '2026-01-17 00:58:35', '2026-01-17 00:58:35', ''),
('02f3538a-c975-4482-a655-45d99aee103f', 'e41854a3-6b44-4e52-b87f-f0d3e14c53ca', 'CPMK-4', 'Mampu menerapkan prinsip dasar ilmu bahan untuk mengevaluasi perilaku material terhadap beban, suhu, dan lingkungan pada kasus teknik sederhana.', 21.43, '2026-01-17 00:58:12', '2026-01-17 00:58:12', 'CPL-01,CPL-03,CPL-04'),
('03106913-ec92-4e12-8dff-f573c28cdcae', 'cdcb2c97-4668-4236-a44f-cd926a9f934b', 'CPMK-5', 'Mampu mengintegrasikan berbagai divais semikonduktor ke dalam sistem elektronika sederhana dan aplikasi daya.', 20.00, '2026-01-17 00:58:25', '2026-01-17 00:58:25', ''),
